gawk '
function ceil(x) {
    return (x == int(x)) ? int(x) : int(x) + (x > 0 ? 1 : 0)
}
function floor(x) {
    return (x == int(x)) ? int(x) : int(x) - (x < 0 ? 1 : 0)
}
BEGIN {
    # FS is space by default
}
NF != 5 { next }
$5 !~ /^[0-9]+ms$/ { next }
{
    path = $3
    # Remove query string (? onwards)
    sub(/\?.*$/, "", path)
    # Remove trailing / unless path is just /
    if (path != "/" && path ~ /\/$/) {
        sub(/\/+$/, "", path)
    }

    # Exclude /healthz and every path under /static/
    if (path == "/healthz") next
    if (path ~ /^\/static\//) next

    status = $4 + 0
    lat = substr($5, 1, length($5) - 2) + 0

    count[path]++
    latencies[path, count[path]] = lat
    if (status >= 500) {
        errs[path]++
    }
    endpoints[path] = 1
}
END {
    # We need to compute p50, p95, err_permille for each endpoint
    print "endpoint\tcount\tp50\tp95\terr_permille"

    # Prepare sorting
    n_ep = 0
    for (ep in endpoints) {
        c = count[ep]
        # Collect latencies into a temporary array and sort
        delete cur_lats
        for (i = 1; i <= c; i++) {
            cur_lats[i] = latencies[ep, i]
        }
        asort(cur_lats)

        # p-th percentile: value at 1-based position ceil(p/100 * count)
        pos50 = ceil(0.50 * c)
        pos95 = ceil(0.95 * c)
        p50 = cur_lats[pos50]
        p95 = cur_lats[pos95]

        # err_permille = floor(1000 * (requests with status >= 500) / count)
        err = floor(1000 * (errs[ep] + 0) / c)

        ep_list[++n_ep] = ep
        res_count[ep] = c
        res_p50[ep] = p50
        res_p95[ep] = p95
        res_err[ep] = err
    }

    # Sort top 5 endpoints:
    # ordered by p95 descending, then count descending, then endpoint ascending (byte order)
    # Simple selection sort or bubble sort since n_ep is small
    for (i = 1; i <= n_ep; i++) {
        for (j = i + 1; j <= n_ep; j++) {
            ep_i = ep_list[i]
            ep_j = ep_list[j]
            swap = 0
            if (res_p95[ep_j] > res_p95[ep_i]) {
                swap = 1
            } else if (res_p95[ep_j] == res_p95[ep_i]) {
                if (res_count[ep_j] > res_count[ep_i]) {
                    swap = 1
                } else if (res_count[ep_j] == res_count[ep_i]) {
                    if (ep_j < ep_i) {
                        swap = 1
                    }
                }
            }
            if (swap) {
                t = ep_list[i]
                ep_list[i] = ep_list[j]
                ep_list[j] = t
            }
        }
    }

    limit = (n_ep < 5 ? n_ep : 5)
    for (i = 1; i <= limit; i++) {
        ep = ep_list[i]
        printf "%s\t%d\t%d\t%d\t%d\n", ep, res_count[ep], res_p50[ep], res_p95[ep], res_err[ep]
    }
}
